41	pub use ram::Ram;
42	pub use spiflash::{SpiFlash, FLASH_SIZE};
43	
44	pub const XIP_BASE: u32 = 0x0200_0000;
45	pub const RAM_BASE: u32 = 0x01c0_0000;
46	pub const OVL_BASE: u32 = 0x0400_0000;
47	pub const SRAM2_BASE: u32 = 0x01f0_0000;
48	/// The stock V13 firmware's .bd_base: what the BT baseband's window register 0x2FC44 reads
49	/// before a firmware writes it (each stock image writes its own .bd_base there: V13 this,
50	/// the SMK-37's v016 0x01C09A18).
51	pub const BT_WINDOW_BASE: u32 = 0x01c0_9e7c;
52	/// The flash offset behind XIP 0x02000000 (the stock layout: the app area starts at 0x4000).
53	pub const XIP_FLASH_OFFSET: usize = 0x4000;
54	
55	#[derive(Debug, Clone, PartialEq, Eq)]
