94	/// The SoC bus: XIP flash + data RAM + modeled peripherals + a logged stub.
95	/// A cheap hasher for register addresses (the SoC's register map): `std`'s SipHash cost the
96	/// SMK-37's stock firmware, which touches registers about a million times a second, a few
97	/// percent of its time.
98	#[derive(Default)]
99	pub struct AddrHasher(u64);
100	
101	impl std::hash::Hasher for AddrHasher {
102	    fn finish(&self) -> u64 {
103	        self.0
104	    }
105	    fn write(&mut self, bytes: &[u8]) {
106	        for &b in bytes {
107	            self.0 = (self.0 ^ b as u64).wrapping_mul(0x100_0000_01b3);
108	        }
109	    }
110	    fn write_u32(&mut self, v: u32) {
111	        self.0 = (v as u64).wrapping_mul(0x9e37_79b9_7f4a_7c15);
112	    }
113	}
114	
115	/// The board around the chip: the FM-1's panel, or the SMK-37's (SMK-37 Pro / Elite, MKE-P37
116	/// and Starrykey 37 Play share one: fm1-to-smk37 docs/01-hardware.md). Same chip, flash
117	/// layout, audio and update path; the panel's wiring differs (smk.rs).
118	#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
119	pub enum Board {
120	    #[default]
121	    Fm1,
122	    Smk37,
123	}
124	
125	impl Board {
126	    /// The board a package is for, from its identity (`FM-1_015`, `SMK-37 Pro_016`, ...).
127	    pub fn of_identity(id: &str) -> Board {
128	        let u = id.to_ascii_uppercase();
129	        if ["SMK", "MKE", "STARRYKEY"].iter().any(|p| u.starts_with(p)) {
130	            Board::Smk37
131	        } else {
132	            Board::Fm1
133	        }
134	    }
135	}
136	
137	pub struct Soc {
138	    pub board: Board,
139	    /// The BT baseband's window base (0x2FC44), as the firmware set it.
140	    bt_window: u32,
141	    pub xip: Vec<u8>,
142	    pub ram: Ram,
143	    pub lcd: Lcd,
144	    /// SPI0 + the external NOR flash (1 MiB; `--flash` image loaded at 0).
145	    pub flash: SpiFlash,
146	    /// Console bytes written through DBG_MSG / UART-style debug boxes.
147	    pub console: Vec<u8>,
148	    /// Overlay RAM (second bank, 0x04000000), written by the app CRT.
149	    pub ovl: Ram,
150	    /// SRAM banks at 0x01f00000 (cleared by the RAM early init).
151	    pub sram2: Ram,
152	    /// monotonic "time" for peripheral counters
153	    pub ticks: u64,
154	    /// Timers, audio DMA, ADC, interrupt controller and the front panel.
155	    pub periph: Periph,
156	    sfr: std::collections::HashMap<u32, u32, std::hash::BuildHasherDefault<AddrHasher>>,
157	    /// Core 0 / 1 paused by the other (C0_CON / C1_CON bit 2 pulses, bit 3 resumes).
158	    paused: [bool; 2],
159	    /// The XIP window continues into the flash chip past the image (the stock layout, which
160	    /// the updater gives every firmware: April OS keeps its samples at flash 0x74000, read
161	    /// through XIP 0x02070000, and waits at boot until it finds them or a blank chip's 0xff).
162	    pub xip_flash: bool,
163	    /// cpu0 released core 1: 0x10008 bit 3 (the stock firmware), or the first `|= 8` (run) on
164	    /// core 1's CON register 0x1EEE004 (M-VAVE's FM1 Open, after the newer AC79 SDK); latched
165	    /// until the runner starts cpu1, as firmwares hold the bit only while they wait for core 1
166	    /// to report in.
167	    pub cpu1_release: bool,
168	    /// core 1 was released once: a later run on 0x1EEE004 is the stock IPC's resume after a
169	    /// pause, not a release.
170	    cpu1_released_once: bool,
171	    /// FM1_AUDIO_TRACE: log each audio half-buffer (debugging the DMA's pace).
172	    audio_trace: bool,
173	    /// The CRC-16 unit's register (0x13504).
174	    crc: u16,
175	    /// The random number generator's state (JL_RAND, 0x13B00: R64L / R64H).
176	    rand: u64,
177	    /// The cores' hardware lock (`lockset` / `lockclr`): which core holds it.
178	    lock_owner: Option<u32>,
179	    /// FM1_GPIO_TRACE: GPIO register writes by address (debugging port use).
180	    pub gpio_writes: Option<std::collections::BTreeMap<u32, u64>>,
181	    unknown_log: Vec<UnknownAccess>,
182	    /// `--flaky-core1`: core 1's RAM loads misread now and then (flaky.rs); None = a good unit.
183	    pub flaky_core1: Option<flaky::FlakyCore1>,
184	    /// The power domain's analog registers.
185	    pub p33: p33::P33,
186	}
187	
188	fn dbg_line(addr: u32) -> &'static str {
189	    match addr & !3 {
190	        0x1eee240 => "wr_en",
191	        0x1eee244 => "msg",
192	        0x1eee248 => "msg_clr",
193	        _ => "dbg",
194	    }
195	}
196	
197	impl Soc {
198	    /// After an erase or page program: the XIP window shows the flash chip, also where the
199	    /// window's contents come from the package (`xip`, the app area as installed). A booted
200	    /// package's window reaches flash 0x93000, and April OS writes its samples from 0x74000
201	    /// and reads them back through XIP.
202	    fn sync_xip(&mut self) {
203	        let Some((a, b)) = self.flash.changed.take() else { return };
204	        if !self.xip_flash {
205	            return;
206	        }
207	        for o in a.max(XIP_FLASH_OFFSET)..b {
208	            match self.xip.get_mut(o - XIP_FLASH_OFFSET) {
209	                Some(x) => *x = self.flash.mem[o],
210	                None => break,
211	            }
212	        }
213	    }
214	
215	    /// A saved flash chip in place of the booted one (fm1-live --flash): each 4 KiB sector that
216	    /// differs goes to the chip and, as the firmware's own erases and programs do, through to
217	    /// the XIP window (whose installed copy would otherwise still show the package's bytes).
218	    pub fn restore_flash(&mut self, image: &[u8]) {
219	        let n = image.len().min(spiflash::FLASH_SIZE);
220	        for at in (0..n).step_by(4096) {
221	            let end = (at + 4096).min(n);
222	            if self.flash.mem[at..end] != image[at..end] {
223	                self.flash.mem[at..end].copy_from_slice(&image[at..end]);
224	                self.flash.changed = Some((at, end));
225	                self.sync_xip();
226	                self.flash.revision = self.flash.revision.wrapping_add(1);
227	            }
228	        }
229	    }
230	
231	    /// `ram_size` in bytes; `xip` = the app binary mapped at XIP_BASE.
232	    pub fn new(ram_size: usize, xip: Vec<u8>) -> Self {
233	        Self {
234	            board: Board::Fm1,
235	            bt_window: BT_WINDOW_BASE,
236	            xip,
237	            ram: Ram::new(ram_size),
238	            ovl: Ram::new(512 * 1024),
239	            sram2: Ram::new(256 * 1024),
240	            lcd: Lcd::new(),
241	            flash: SpiFlash::new(),
242	            console: Vec::new(),
243	            ticks: 0,
244	            periph: Periph::default(),
245	            sfr: Default::default(),
246	            paused: [false; 2],
247	            lock_owner: None,
248	            crc: 0,
249	            rand: 0x9e37_79b9_7f4a_7c15,
250	            cpu1_release: false,
251	            cpu1_released_once: false,
252	            audio_trace: std::env::var_os("FM1_AUDIO_TRACE").is_some(),
253	            xip_flash: true,
254	            gpio_writes: std::env::var("FM1_GPIO_TRACE").ok().map(|_| Default::default()),
255	            unknown_log: Vec::new(),
256	            flaky_core1: None,
257	            p33: Default::default(),
258	        }
259	    }
260	
261	    /// A load by core 1: what `read32` returns, unless a flaky core 1 misreads it (RAM only).
262	    pub fn core1_read32(&mut self, addr: u32) -> u32 {
263	        let v = self.read32(addr);
264	        self.core1_misread(addr, 4, v)
265	    }
266	
267	    pub fn core1_read16(&mut self, addr: u32) -> u16 {
268	        let v = self.read16(addr);
269	        self.core1_misread(addr, 2, v as u32) as u16
270	    }
271	
272	    pub fn core1_read8(&mut self, addr: u32) -> u8 {
273	        let v = self.read8(addr);
274	        self.core1_misread(addr, 1, v as u32) as u8
275	    }
276	
277	    #[inline]
278	    fn core1_misread(&mut self, addr: u32, size: u32, v: u32) -> u32 {
279	        match self.flaky_core1.as_mut() {
280	            Some(f) if (addr.wrapping_sub(RAM_BASE) as usize) < self.ram.len() => f.load(addr, size, v),
281	            _ => v,
282	        }
283	    }
284	
285	    /// Wire the chip into `board`'s panel (and its flash chip's id).
286	    pub fn set_board(&mut self, board: Board) {
287	        self.board = board;
288	        self.periph.board = board;
289	        if board == Board::Smk37 {
290	            self.flash.jedec = [0xeb, 0x60, 0x14];
291	        }
292	    }
293	
294	    /// All unknown accesses so far — the peripheral bring-up TODO list.
295	    /// Advance the peripheral clock by `n` CPU cycles, moving any finished
296	    /// audio half out of RAM (int32 L/R holding a 24-bit sample in the low
297	    /// bits — Felucca writes Q15 << 7, audio.c OUT_SHIFT — so >> 8 to i16).
298	    pub fn advance(&mut self, n: u64) {
299	        let due = self.periph.advance(n);
300	        if let Some((at, b)) = due.uart_rx {
301	            self.write8(at, b);
302	        }
303	        if let Some((adr, words)) = due.audio_half {
304	            if self.audio_trace {
305	                eprintln!("half {} ms {}", self.periph.ms(), self.periph.cycles);
306	            }
307	            for i in 0..words {
308	                let w = self.read32(adr.wrapping_add(i * 4)) as i32;
309	                self.periph.audio.push((w >> 8).clamp(-32768, 32767) as i16);
310	            }
311	        }
312	    }
313	
314	    /// The highest-priority enabled pending interrupt: (irq, prio).
315	    #[inline]
316	    pub fn pending_irq(&self) -> Option<(u8, u8)> {
317	        self.periph.pending_irq()
318	    }
319	
320	    /// Core `core` (0, 1) is paused by the other through its CON register's bit 2
321	    /// (0x1EEE000 / 0x1EEE004): the stock firmware stops core 1 around flash work.
322	    pub fn core_paused(&self, core: u32) -> bool {
323	        core < 2 && self.paused[core as usize]
324	    }
325	
326	    /// The highest-priority interrupt pending for core `core` (its own enable bank).
327	    pub fn pending_irq_for(&self, core: u32) -> Option<(u8, u8)> {
328	        self.periph.pending_irq_for(core)
329	    }
330	
331	    pub fn unknown_accesses(&self) -> &[UnknownAccess] {
332	        &self.unknown_log
333	    }
334	
335	    /// The debug console contents (DBG_MSG box writes).
336	    pub fn console_string(&self) -> String {
337	        String::from_utf8_lossy(&self.console).into_owned()
338	    }
339	
340	    fn log_unknown(&mut self, addr: u32, width: u8, is_write: bool, value: u32) {
341	        self.unknown_log.push(UnknownAccess {
342	            addr,
343	            width,
344	            is_write,
345	            value,
346	        });
347	        // keep the last 8192..16384 (dropping one at a time shifted the whole log per access)
348	        if self.unknown_log.len() >= 16384 {
349	            self.unknown_log.drain(..8192);
350	        }
351	    }
352	
353	    fn region(&self, addr: u32) -> Region {
354	        match addr {
355	            a if a >= XIP_BASE && (a - XIP_BASE) < self.xip.len() as u32 => Region::Xip,
356	            // past the loaded image the XIP window still shows the flash chip (the stock
357	            // firmware reads its USR preset area, which it writes over SPI, through XIP)
358	            a if self.xip_flash && a >= XIP_BASE && (a - XIP_BASE) as usize + XIP_FLASH_OFFSET < spiflash::FLASH_SIZE => Region::XipFlash,
359	            a if a >= RAM_BASE && (a - RAM_BASE) < self.ram.len() as u32 => Region::Ram,
360	            a if a >= OVL_BASE && (a - OVL_BASE) < self.ovl.len() as u32 => Region::Ovl,
361	            a if a >= SRAM2_BASE && (a - SRAM2_BASE) < self.sram2.len() as u32 => Region::Sram2,
362	            0x1eee000..=0x1eee0ff => Region::Irqc,
363	            0x1eef000..=0x1eef3ff => Region::Irqc2,
364	            0x12e00..=0x12e3f => Region::Alnk,
365	            0x50000..=0x501ff => Region::Gpio,
366	            0x51000..=0x5103f => Region::Iomap,
367	            0x10000..=0x1001f => Region::Clk,
368	            0x10400..=0x1091f => Region::Timer,
369	            0x11c00..=0x11c1f => Region::Spi0,
370	            0x11d00..=0x11d1f => Region::Spi1,
371	            0x11e00..=0x11e1f => Region::Spi2,
372	            0x11800..=0x1183f => Region::Usb,
373	            // the second USB PHY (the SMK-37's LED commons at 0x16A0C, its pads used as GPIO; its
374	            // stock firmware powers the PHY up at boot and waits for 0x16800 bit 4). The FM-1's
375	            // stock firmware touches the block too, as before: unknown.
376	            0x16800..=0x16a1f if self.board == Board::Smk37 => Region::Usb,
377	            0x12100..=0x1212f => Region::Uart1,
378	            0x13100..=0x1311f => Region::Adc,
379	            0x13500..=0x1350f => Region::Crc,
380	            0x13b00..=0x13b07 => Region::Rand,
381	            0x11900..=0x119ff => Region::Ana,
382	            0x13e08..=0x13e0f => Region::P33,
383	            0x20000..=0x2ffff => Region::Bt,
384	            0x1eee240..=0x1eee24f => Region::Dbg,
385	            _ => Region::Unknown,
386	        }
387	    }
388	
389	    fn sfr_get(&mut self, addr: u32) -> u32 {
390	        *self.sfr.get(&addr).unwrap_or(&0)
391	    }
392	
393	    fn sfr_set(&mut self, addr: u32, v: u32) {
394	        self.sfr.insert(addr, v);
395	    }
396	
397	    /// SPI1/MMIO side effects on 32-bit writes.
398	    fn spi1_write(&mut self, addr: u32, value: u32) {
399	        match addr {
400	            0x11d00 => {
401	                // CON: bit14 clears the pending transfer-done (and its IRQ 16)
402	                if value & 0x4000 != 0 {
403	                    self.periph.spi1_pending = false;
404	                }
405	                let stored = self.sfr_get(addr);
406	                self.sfr_set(addr, (stored & !0x4000) | (value & !0x4000));
407	            }
408	            0x11d04 => self.sfr_set(addr, value), // BAUD
409	            0x11d08 => {
410	                // BUF: single byte, D/C = PC8 state (SMK-37: PB5; its group B is the pad LEDs)
411	                if let Some(dc) = self.lcd_dc() {
412	                    self.lcd.feed(value as u8, dc);
413	                }
414	                self.sfr_set(addr, value);
415	                self.spi1_done(1);
416	            }
417	            0x11d0c => self.sfr_set(addr, value), // ADR
418	            0x11d10 => {
419	                // CNT: DMA `value` bytes from RAM[ADR] through the panel
420	                let adr = self.sfr_get(0x11d0c);
421	                let n = value.min(0x40000);
422	                // the DMA source is a bus address (RAM, SRAM or XIP)
423	                let bytes: Vec<u8> = (0..n).map(|i| self.read8(adr.wrapping_add(i))).collect();
424	                match self.lcd_dc() {
425	                    Some(dc) => {
426	                        for b in bytes {
427	                            self.lcd.feed(b, dc);
428	                        }
429	                    }
430	                    None => self.periph.smk.pad_frame(&bytes),
431	                }
432	                self.sfr_set(addr, 0);
433	                self.spi1_done(n);
434	            }
435	            _ => self.sfr_set(addr, value),
436	        }
437	    }
438	
439	    /// Where SPI1's bytes go: the LCD with its D/C pin's state (FM-1: PC8; SMK-37: PB5, while
440	    /// IOMAP_CON1 bit 4 picks pin group A), or None: the SMK-37's pad LEDs (group B).
441	    fn lcd_dc(&mut self) -> Option<bool> {
442	        match self.board {
443	            Board::Fm1 => Some(self.sfr_get(0x50080) & 0x100 != 0),
444	            Board::Smk37 => (self.sfr_get(0x51020) & 0x10 == 0).then(|| self.sfr_get(0x50040) & 0x20 != 0),
445	        }
446	    }
447	
448	    /// SPI2 (0x11E00, CON/BAUD/BUF/ADR/CNT like SPI1): the stock firmware shifts the key
449	    /// matrix's column pattern into the two 74HC595s with it, one 2-byte DMA per column,
450	    /// driven by its IRQ 37 handler (which also reads the rows and pulses RCLK on PA1).
451	    fn spi2_write(&mut self, addr: u32, value: u32) {
452	        match addr {
453	            0x11e00 => {
454	                if value & 0x4000 != 0 {
455	                    self.periph.spi2_pending = false;
456	                }
457	                self.sfr_set(addr, value & !0xc000);
458	            }
459	            0x11e08 => {
460	                self.periph.sr_shift_byte(value as u8);
461	                self.sfr_set(addr, value);
462	                self.spi2_started(1);
463	            }
464	            0x11e10 => {
465	                let adr = self.sfr_get(0x11e0c);
466	                for i in 0..value.min(64) {
467	                    let b = self.read8(adr.wrapping_add(i));
468	                    self.periph.sr_shift_byte(b);
469	                }
470	                self.sfr_set(addr, 0);
471	                self.spi2_started(value);
472	            }
473	            _ => self.sfr_set(addr, value),
474	        }
475	    }
476	
477	    fn spi2_started(&mut self, bytes: u32) {
478	        let con = self.sfr_get(0x11e00);
479	        let baud = self.sfr_get(0x11e04);
480	        self.periph.spi2_start(bytes, baud, con & 0x2000 != 0);
481	    }
482	
483	    /// A SPI1 transfer finished (instantly here): with CON bit 13 (interrupt enable) that is
484	    /// IRQ 16, the stock LCD driver's DMA-done (its layer flush waits for the handler).
485	    /// (SMK-37: it takes the bytes' time on the wire, see `Periph::spi1_start`.)
486	    fn spi1_done(&mut self, bytes: u32) {
487	        let irq = self.sfr_get(0x11d00) & 0x2000 != 0;
488	        if self.board == Board::Smk37 {
489	            let baud = self.sfr_get(0x11d04);
490	            self.periph.spi1_start(bytes, baud, irq);
491	        } else if irq {
492	            self.periph.spi1_pending = true;
493	        }
494	    }
495	
496	    fn timer_read(&mut self, addr: u32) -> u32 {
497	        // "time" base ticks so timeout/wait loops make progress; count
498	        // registers report a moving value, the rest stored bits.
499	        self.ticks = self.ticks.wrapping_add(1);
500	        if addr & 0xff == 0x04 {
501	            let t = (self.ticks * 7) as u32;
502	            return t;
503	        }
504	        self.sfr_get(addr)
505	    }
506	}
