574	    // RAM fast paths: same results as the region dispatch below (byte and
575	    // halfword accesses select within the aligned word), without walking it
576	
577	    #[inline(always)]
578	    fn read8(&mut self, addr: u32) -> u8 {
579	        let o = addr.wrapping_sub(RAM_BASE);
580	        if (o as usize) < self.ram.len() {
581	            return self.ram.read8(o);
582	        }
583	        self.read32(addr & !3).to_le_bytes()[(addr & 3) as usize]
584	    }
