586	    #[inline(always)]
587	    fn read16(&mut self, addr: u32) -> u16 {
588	        // halfwords sit at offsets 0 and 2 of the word (the old `>> 8` for
589	        // offset 2 returned bytes 1-2 and sheared every 16-bit pixel canvas)
590	        let v = self.read32(addr & !3);
591	        (v >> ((addr & 2) * 8)) as u16
592	    }
593	
594	    #[inline(always)]
595	    fn read32(&mut self, addr: u32) -> u32 {
596	        let o = addr.wrapping_sub(RAM_BASE) as usize;
597	        if o + 4 <= self.ram.len() {
598	            return self.ram.read32(o as u32);
599	        }
600	        let x = addr.wrapping_sub(XIP_BASE) as usize;
601	        if x + 4 <= self.xip.len() {
602	            return u32::from_le_bytes([self.xip[x], self.xip[x + 1], self.xip[x + 2], self.xip[x + 3]]);
603	        }
604	        self.read32_slow(addr)
605	    }
606	
607	    #[inline(always)]
608	    fn write8(&mut self, addr: u32, value: u8) {
609	        let o = addr.wrapping_sub(RAM_BASE);
610	        if (o as usize) < self.ram.len() {
611	            return self.ram.write8(o, value);
612	        }
613	        self.write8_slow(addr, value)
614	    }
615	
616	    #[inline(always)]
617	    fn write16(&mut self, addr: u32, value: u16) {
618	        // merged at (addr & 2) within the aligned word, as the slow path does
619	        let o = (addr & !1).wrapping_sub(RAM_BASE) as usize;
620	        if o + 2 <= self.ram.len() && addr & 1 == 0 {
621	            return self.ram.write16(o as u32, value);
622	        }
623	        self.write16_slow(addr, value)
624	    }
625	
626	    #[inline(always)]
627	    fn write32(&mut self, addr: u32, value: u32) {
628	        let o = addr.wrapping_sub(RAM_BASE) as usize;
629	        if o + 4 <= self.ram.len() {
630	            return self.ram.write32(o as u32, value);
631	        }
632	        self.write32_slow(addr, value)
633	    }
634	}
