636	impl Soc {
637	    #[inline(never)]
638	    fn read32_slow(&mut self, addr: u32) -> u32 {
639	        match self.region(addr) {
640	            Region::Xip => {
641	                let o = (addr - XIP_BASE) as usize;
642	                let g = |i: usize| self.xip.get(i).copied().unwrap_or(0);
643	                u32::from_le_bytes([g(o), g(o + 1), g(o + 2), g(o + 3)])
644	            }
645	            Region::Ram => self.ram.read32(addr - RAM_BASE),
646	            Region::XipFlash => {
647	                let o = (addr - XIP_BASE) as usize + XIP_FLASH_OFFSET;
648	                let g = |i: usize| self.flash.mem.get(i).copied().unwrap_or(0xff);
649	                u32::from_le_bytes([g(o), g(o + 1), g(o + 2), g(o + 3)])
650	            }
651	            Region::Ovl => self.ovl.read32(addr - OVL_BASE),
652	            Region::Sram2 => self.sram2.read32(addr - SRAM2_BASE),
653	            Region::Irqc => {
654	                // 0x1eee008 bit 14: controller ready (the early init spins on it);
655	                // 0x1eee000 / 0x1eee004 (C0_CON / C1_CON): see `core_paused`
656	                let v = self.sfr_get(addr);
657	                match addr {
658	                    0x1eee008 => v | 0x4000,
659	                    0x1eee000 | 0x1eee004 => {
660	                        let core = ((addr >> 2) & 1) as usize;
661	                        (v & !0x14) | if self.paused[core] { 0x10 } else { 0 }
662	                    }
663	                    _ => v,
664	                }
665	            }
666	            // (the second USB PHY ready: bit 4 of its control word, once it is powered up)
667	            Region::Usb if addr == 0x16800 => self.sfr_get(addr) | 0x10,
668	            Region::Iomap | Region::Usb | Region::Clk => self.sfr_get(addr),
669	            // JL_ANA (analog: WLA, DAC trim). 0x11978 is the DAC trim measurement after the
670	            // strobe at the same word: bit 5 = conversion done, bits 8-15 = the value (mid
671	            // scale here), bit 18 = "this trim step is right". With these the stock
672	            // firmware's audio_ana calibration finishes at once instead of polling forever
673	            // (a trim only nudges the DAC's DC offset).
674	            Region::Ana => {
675	                let v = self.sfr_get(addr);
676	                if addr == 0x11978 { (v & !0xff00) | 0x4_0000 | 0x8000 | 0x20 } else { v }
677	            }
678	            // the Bluetooth baseband (bsfr 0x20000; no radio here): reads 0, writes are
679	            // dropped (self-clearing requests like bt_clkn_compare_arm's capture at 0x2001C
680	            // must read done), except 0x2FC44, the base of the RAM window its buffers live in,
681	            // which the BT init writes (its .bd_base, which opens the BT bss, SDK
682	            // btctler_lib_bss.ld). The stock BT stack checks buffers against it: descriptors
683	            // within 2 KiB and below its own .bd_base + 1088, bulk buffers within 32 KiB; with
684	            // V13's base kept, the SMK-37 firmware's check failed and it reset.
685	            Region::Bt => {
686	                if addr == 0x2fc44 { self.bt_window } else { 0 }
687	            }
688	            Region::Gpio | Region::Adc | Region::Alnk | Region::Irqc2 | Region::Uart1 => {
689	                match self.periph.read(addr) {
690	                    Some(v) => v,
691	                    None => self.sfr_get(addr),
692	                }
693	            }
694	            Region::Timer => {
695	                match self.periph.read(addr) {
696	                    Some(v) => v,
697	                    None => self.timer_read(addr),
698	                }
699	            }
700	            Region::Spi0 => self.flash.read(addr),
701	            // SPI2: transfers finish at once (CON bit 15 reads done)
702	            Region::Spi2 => self.sfr_get(addr) | if addr == 0x11e00 { 0x8000 } else { 0 },
703	            Region::Spi1 => {
704	                if addr == 0x11d00 {
705	                    // CON: transfer-done (the FM-1: always, so polls finish; the SMK-37: once the
706	                    // bytes have gone out)
707	                    let busy = self.board == Board::Smk37 && self.periph.cycles < self.periph.spi1_done_at;
708	                    self.sfr_get(addr) | if busy { 0 } else { 0x8000 }
709	                } else if addr == 0x11d10 {
710	                    self.sfr_get(addr)
711	                } else {
712	                    self.sfr_get(addr)
713	                }
714	            }
715	            Region::Dbg => self.sfr_get(addr),
716	            Region::Crc => if addr == 0x13504 { self.crc as u32 } else { 0 },
717	            // JL_RAND (0x13B00 R64L, 0x13B04 R64H): a new number at every read, from a fixed
718	            // seed so runs repeat. Read as 0 it hung the stock firmware ~8 s after boot: a
719	            // routine in its audio driver parks the task when a random word equals a fixed
720	            // descrambled one, which real hardware never hits.
721	            Region::Rand => {
722	                let mut x = self.rand;
723	                x ^= x << 13;
724	                x ^= x >> 7;
725	                x ^= x << 17;
726	                self.rand = x;
727	                (if addr == 0x13b00 { x } else { x >> 32 }) as u32
728	            }
729	            Region::P33 => self.p33.read(addr),
730	            Region::Unknown => {
731	                self.log_unknown(addr, 4, false, 0);
732	                0
733	            }
734	        }
735	    }
736	
737	    #[inline(never)]
738	    fn write8_slow(&mut self, addr: u32, value: u8) {
739	        let cur = self.read32(addr & !3);
740	        let shift = (addr & 3) * 8;
741	        let mask = !(0xffu32 << shift);
742	        let merged = (cur & mask) | ((value as u32) << shift);
743	        self.write32(addr & !3, merged);
744	    }
745	
746	    #[inline(never)]
747	    fn write16_slow(&mut self, addr: u32, value: u16) {
748	        let cur = self.read32(addr & !3);
749	        let shift = (addr & 2) * 8;
750	        let mask = !(0xffffu32 << shift);
751	        let merged = (cur & mask) | ((value as u32) << shift);
752	        self.write32(addr & !3, merged);
753	    }
754	
755	    #[inline(never)]
756	    fn write32_slow(&mut self, addr: u32, value: u32) {
757	        match self.region(addr) {
758	            Region::Xip | Region::XipFlash => self.log_unknown(addr, 4, true, value), // flash writes go via the ROM
759	            Region::Ram => self.ram.write32(addr - RAM_BASE, value),
760	            Region::Ovl => self.ovl.write32(addr - OVL_BASE, value),
761	            Region::Sram2 => self.sram2.write32(addr - SRAM2_BASE, value),
762	            Region::Irqc => {
763	                if addr == 0x1eee000 || addr == 0x1eee004 {
764	                    // C0_CON / C1_CON: writing bit 2 pauses that core (bit 4 reads "paused");
765	                    // a write with bit 3 and without bit 2 runs it again. Both are pulses:
766	                    // the stock IPC pauses with `|= 4` and resumes with `|= 8` on the same word.
767	                    let core = ((addr >> 2) & 1) as usize;
768	                    if value & 4 != 0 {
769	                        self.paused[core] = true;
770	                    } else if value & 8 != 0 {
771	                        self.paused[core] = false;
772	                        if core == 1 && !self.cpu1_released_once {
773	                            // M-VAVE's FM1 Open SDK releases core 1 here (C1_CON |= 8), not at 0x10008
774	                            // (once: the stock firmware's IPC resumes core 1 the same way)
775	                            self.cpu1_released_once = true;
776	                            self.cpu1_release = true;
777	                            self.periph.next_due = 0;
778	                        }
779	                    }
780	                    self.sfr_set(addr, value & !0x14);
781	                } else {
782	                    self.sfr_set(addr, value);
783	                }
784	            }
785	            Region::Gpio => {
786	                if let Some(h) = self.gpio_writes.as_mut() {
787	                    *h.entry(addr).or_insert(0) += 1;
788	                }
789	                // PD0 drives the flash chip select; PA1/PA3/PA4 clock the
790	                // key-matrix shift registers
791	                if addr == 0x500c0 {
792	                    self.flash.set_cs(value & 1 == 0);
793	                    self.sync_xip();
794	                }
795	                self.periph.write(addr, value);
796	                self.sfr_set(addr, value)
797	            }
798	            Region::Alnk | Region::Irqc2 => {
799	                if !self.periph.write(addr, value) {
800	                    self.sfr_set(addr, value);
801	                }
802	            }
803	            Region::Spi0 => {
804	                self.flash.write(addr, value);
805	                self.sync_xip();
806	            }
807	            Region::Iomap => self.sfr_set(addr, value),
808	            Region::Ana => self.sfr_set(addr, value),
809	            Region::P33 => self.p33.write(addr, value),
810	            Region::Bt => {
811	                if addr == 0x2fc44 {
812	                    self.bt_window = value;
813	                }
814	            }
815	            Region::Clk => {
816	                if addr == 0x10008 && value & 8 != 0 && self.sfr_get(addr) & 8 == 0 {
817	                    self.cpu1_released_once = true;
818	                    self.cpu1_release = true;
819	                    self.periph.next_due = 0; // the runner looks at it before the next instruction
820	                }
821	                self.sfr_set(addr, value)
822	            }
823	            Region::Usb => {
824	                if addr == 0x16a0c && self.board == Board::Smk37 {
825	                    self.periph.smk.commons = value;
826	                }
827	                self.sfr_set(addr, value)
828	            }
829	            Region::Uart1 => {
830	                if !self.periph.write(addr, value) {
831	                    self.sfr_set(addr, value);
832	                }
833	            }
834	            Region::Adc => {
835	                if !self.periph.write(addr, value) {
836	                    self.sfr_set(addr, value);
837	                }
838	            }
839	            Region::Timer => {
840	                if !self.periph.write(addr, value) {
841	                    self.sfr_set(addr, value);
842	                }
843	            }
844	            Region::Spi1 => self.spi1_write(addr, value),
845	            Region::Spi2 => self.spi2_write(addr, value),
846	            // the CRC-16 unit (chip_crc16): [+4] = the register (the SDK seeds it with 0),
847	            // each write to [+0] feeds one byte through CRC-16/CCITT (0x1021, MSB first).
848	            // The stock NOR file system checks every directory entry with it.
849	            Region::Rand => {}
850	            Region::Crc => match addr {
851	                0x13500 => {
852	                    let mut c = self.crc ^ ((value as u16 & 0xff) << 8);
853	                    for _ in 0..8 {
854	                        c = if c & 0x8000 != 0 { (c << 1) ^ 0x1021 } else { c << 1 };
855	                    }
856	                    self.crc = c;
857	                }
858	                0x13504 => self.crc = value as u16,
859	                _ => {}
860	            },
861	            Region::Dbg => {
862	                match dbg_line(addr) {
863	                    "msg" => {
864	                        self.console.extend_from_slice(&value.to_le_bytes());
865	                    }
866	                    _ => {}
867	                }
868	                self.sfr_set(addr, value);
869	            }
870	            Region::Unknown => self.log_unknown(addr, 4, true, value),
871	        }
872	    }
873	}
