1	//! Timed peripherals and the front panel, modelled from what Felucca's HAL
2	//! (reference/Felucca/firmware/hal/*.h) programs and from the RE docs:
3	//!
4	//! * a cycle counter (`hz`, one instruction per cycle; 240 MHz like the
5	//!   chip, lower for live play) paces everything, and the timers convert
6	//!   cycles to real time so the firmware's clock stays right at any `hz`;
7	//! * with `skip_idle`, a tight loop polling TIMER4 outside an ISR (a delay)
8	//!   jumps the clock to the next timed event instead of spinning;
9	//! * TIMER4 `0x10800`: free-running 24 MHz time base (CNT at +4);
10	//! * TIMER5 `0x10900`: 10 kHz tick (PRD at 6 MHz), pending CON bit 15,
11	//!   acknowledged by writing bit 14, IRQ 63;
12	//! * ALNK0 `0x12E00`: I2S out, double-buffered DMA of `LEN` int32 words per
13	//!   half (L/R, a 24-bit sample in the low bits of each word) at 44.1 kHz; a finished half sets
14	//!   CON2 bit 7 (cleared by writing bit 3), CON0 bit 15 = the half playing,
15	//!   IRQ 11;
16	//! * SARADC `0x13100`: CON (start = bit 6, done = bit 7, channel bits 8-11),
17	//!   RES = 10-bit value — MASTER pot on ch 4, battery on ch 3;
18	//! * the interrupt controller: enable/priority nibbles at `0x1EEF100` for cpu0 and
19	//!   `0x1EEF300` for cpu1 (one per source, bit 0 enable, bits 1-3 priority; the sources are
20	//!   shared, each core takes what its own bank enables), software latch set/clear at
21	//!   `0x1EEF1A0/1A4` (bit b = IRQ 120+b; the stock RTOS's context switch is bit 7 - cnum, its
22	//!   cross-core doorbell another bit), one RAM vector table at `0x01C7FE00` for both;
23	//! * the OS tick block at `0x1EEF0EC` (stock firmware): b[+0] bit 0 enable, bit 6 written =
24	//!   acknowledge, bit 7 read = pending; `+4` the count (written: restart), `+8` the period
25	//!   (`os_start`: clk/100, 10 ms); IRQ 3 (FM-1-RE docs/io/02-rtos.md);
26	//! * UART1 `0x12100` (MIDI IN, the TRS jack): bytes from `Action::Midi` arrive one per
27	//!   31250-baud byte time (320 us) and are DMA'd into the ring RXSADR..RXEADR. CON0 (the JieLi
28	//!   layout, SDK uart driver + Felucca hal/fm1_uart.h): bit 0 on, 2/3/5 TX/RX/timeout IE, 6 RX
29	//!   DMA, written bit 7 latches the bytes received since the last latch into HRXCNT (+0x28),
30	//!   written bits 10/12/13 clear the timeout / RX / TX pendings (bits 11/14/15). RX pending =
31	//!   RXCNT bytes since the last latch, timeout = OTCNT UART clocks (48 MHz) of silence after a
32	//!   byte; IRQ 20. A TX DMA (TXCNT written) finishes at once: no TX pin on the board;
33	//! * the key/encoder matrix: 11 columns from two 74HC595s (PA4 SER, PA3
34	//!   SRCLK, PA1 RCLK, MSB first, a low bit selects the column), rows PA0,
35	//!   PA5-PA8, PB7 with pull-ups (low = closed).
36	
37	use std::collections::VecDeque;
38	
39	pub const CPU_HZ: u64 = 240_000_000;
40	/// TIMER4 counts the 24 MHz crystal; TIMER5 runs from OSC/4.
41	const T4_HZ: u64 = 24_000_000;
42	const T5_HZ: u64 = 6_000_000;
43	/// TIMER4 ticks per I2S frame (Felucca audio.c DAC_TICKS: 44.1 kHz).
44	const FRAME_T4: u64 = 544;
45	
46	pub const IRQ_ALNK0: u8 = 11;
47	pub const IRQ_TIMER5: u8 = 63;
48	pub const IRQ_OS_TICK: u8 = 3;
49	pub const IRQ_SPI1: u8 = 16;
50	pub const IRQ_SARADC: u8 = 24;
51	pub const IRQ_SPI2: u8 = 37;
