85	/// The JL_TIMER prescaler table: CON bits 4-7 index it (the stock firmware's own copy at
86	/// 0x0204F8C0 reads the same).
87	const TMR_DIV: [u64; 16] = [1, 4, 16, 64, 2, 8, 32, 128, 256, 1024, 4096, 16384, 512, 2048, 8192, 32768];
88	
89	/// TIMER0..3 (`0x10400 + 0x100 * n`, IRQ 4 + n): CON (bit 0 on; low nibble 9 = the 24 MHz
90	/// crystal, bits 4-7 the prescaler, bit 15 pending, written bit 14 clears it), CNT (where it
91	/// counts from), PRD (the count that raises the interrupt and restarts). The stock firmware
92	/// runs its usr_timer engine (the 2 ms ADC scan, key scan) on TIMER1.
93	#[derive(Clone, Copy, Default)]
94	struct Tmr {
95	    con: u32,
96	    prd: u32,
97	    cnt0: u32,
98	    start: u64,
99	    next: u64,
100	    pending: bool,
101	}
