316	/// What the cycle advance found due; the caller moves the audio half out
317	/// of RAM (and a received UART byte into it) because the peripheral block has no bus of its own.
318	#[derive(Debug, Default)]
319	pub struct Due {
320	    /// A half buffer finished playing: (RAM address, words).
321	    pub audio_half: Option<(u32, u32)>,
322	    /// A UART byte the RX DMA wrote: (address, byte).
323	    pub uart_rx: Option<(u32, u8)>,
