327	impl Periph {
328	    pub fn ms(&self) -> u64 {
329	        self.cycles * 1000 / self.hz
330	    }
331	
332	    pub fn cycle_of_ms(&self, ms: u64) -> u64 {
333	        ms * self.hz / 1000
334	    }
335	
336	    fn t5_period(&self) -> u64 {
337	        (self.t5_prd.max(1) as u64 * self.hz / T5_HZ).max(1)
338	    }
339	
340	    /// CPU cycles per count of TIMER0..3 `i` (the crystal through the prescaler).
341	    fn tmr_cycles_per_count(&self, i: usize) -> u64 {
342	        TMR_DIV[((self.tmr[i].con >> 4) & 15) as usize] * self.hz / T4_HZ
343	    }
344	
345	    fn tmr_arm(&mut self, i: usize) {
346	        let t = self.tmr[i];
347	        if t.con & 3 == 0 || t.prd == 0 {
348	            self.tmr[i].next = u64::MAX;
349	            return;
350	        }
351	        let left = t.prd.saturating_sub(t.cnt0).max(1) as u64;
352	        self.tmr[i].start = self.cycles;
353	        self.tmr[i].next = self.cycles + left * self.tmr_cycles_per_count(i).max(1);
354	    }
355	
356	    /// The OS tick: 10 ms however the period register is scaled (os_start writes clk/100).
357	    fn tick_period(&self) -> u64 {
358	        (self.hz / 100).max(1)
359	    }
360	
361	    fn half_period(&self) -> u64 {
362	        (self.alnk_len.max(2) as u64 / 2 * FRAME_T4 * self.hz / T4_HZ).max(1)
363	    }
364	
365	    fn enc_step(&self) -> u64 {
366	        // contacts move one quadrature state every 2 ms (SMK-37: 4 ms, the port's decoder takes a
367	        // state once it has held for two 1.6 ms scan frames)
368	        if self.board == crate::Board::Smk37 { self.hz / 250 } else { self.hz / 500 }
369	    }
370	
371	    /// The next cycle at which something timed happens.
372	    fn next_event(&self) -> u64 {
373	        let mut n = self.t5_next.min(self.alnk_next).min(self.tick_next).min(self.spi2_next).min(self.adc_next).min(self.spi1_irq_at);
374	        n = n.min(self.uart.next).min(self.uart.ot_next);
375	        for t in &self.tmr {
376	            n = n.min(t.next);
377	        }
378	        if let Some((at, _)) = self.script.front() {
379	            n = n.min(*at);
380	        }
381	        for i in 0..8 {
382	            if self.enc_pending[i] != 0 {
383	                n = n.min(self.enc_next[i]);
384	            }
385	        }
386	        n
387	    }
388	
389	    /// Advance `n` cycles; returns what came due.
390	    pub fn advance(&mut self, n: u64) -> Due {
391	        self.cycles += n;
392	        let mut due = Due::default();
393	        if self.cycles < self.next_due {
394	            return due;
395	        }
396	        if self.cycles >= self.t5_next {
397	            self.t5_pending = true;
398	            let period = self.t5_period();
399	            self.t5_next += period;
400	            if self.t5_next <= self.cycles {
401	                self.t5_next = self.cycles + period;
402	            }
403	        }
404	        if self.cycles >= self.spi2_next {
405	            self.spi2_pending = true;
406	            self.spi2_next = u64::MAX;
407	        }
408	        if self.cycles >= self.spi1_irq_at {
409	            self.spi1_irq_at = u64::MAX;
410	            self.spi1_pending = true;
411	        }
412	        if self.cycles >= self.adc_next {
413	            self.adc_next = u64::MAX;
414	            self.adc_done = true;
415	            self.adc_irq = self.adc_con & 0x20 != 0;
416	        }
417	        for i in 0..4 {
418	            if self.cycles >= self.tmr[i].next {
419	                self.tmr[i].pending = true;
420	                self.tmr[i].cnt0 = 0;
421	                let per = self.tmr[i].prd.max(1) as u64 * self.tmr_cycles_per_count(i).max(1);
422	                self.tmr[i].start = self.tmr[i].next;
423	                self.tmr[i].next += per;
424	                if self.tmr[i].next <= self.cycles {
425	                    self.tmr[i].next = self.cycles + per;
426	                }
427	            }
428	        }
429	        if self.cycles >= self.tick_next {
430	            self.tick_pending = true;
431	            self.tick_start = self.tick_next;
432	            self.tick_next += self.tick_period();
433	            if self.tick_next <= self.cycles {
434	                self.tick_next = self.cycles + self.tick_period();
435	            }
436	        }
437	        if self.cycles >= self.alnk_next {
438	            let words = self.alnk_len.max(2);
439	            due.audio_half = Some((self.alnk_adr.wrapping_add(self.alnk_half * words * 4), words));
440	            self.alnk_half ^= 1;
441	            // every channel CON1 sets up pends with the block: FM1 Open's driver takes its
442	            // interrupt from the receive channel 0 (pending bit 4), the stock one from transmit
443	            // channel 3 (bit 7)
444	            for ch in 0..4 {
445	                if (self.alnk_con1 >> (4 * ch)) & 0xf != 0 {
446	                    self.alnk_pend |= 0x10 << ch;
447	                }
448	            }
449	            self.alnk_pend |= 0x80;
450	            self.alnk_next += self.half_period();
451	            self.audio_halves += 1;
452	        }
453	        if self.cycles >= self.uart.next {
454	            due.uart_rx = self.uart_receive();
455	        }
456	        if self.cycles >= self.uart.ot_next {
457	            self.uart.ot_next = u64::MAX;
458	            if self.uart.con0 & 1 != 0 {
459	                self.uart.otpnd = true;
460	                self.uart_update();
461	            }
462	        }
463	        for i in 0..8 {
464	            if self.enc_pending[i] != 0 && self.cycles >= self.enc_next[i] {
465	                let s = self.enc_state[i] as i32;
466	                self.enc_state[i] = ((s + self.enc_pending[i].signum()) & 3) as u8;
467	                self.enc_pending[i] -= self.enc_pending[i].signum();
468	                self.enc_next[i] = self.cycles + self.enc_step();
469	            }
470	        }
471	        while let Some((at, _)) = self.script.front() {
472	            if *at > self.cycles {
473	                break;
474	            }
475	            let (_, a) = self.script.pop_front().unwrap();
476	            self.apply(&a);
477	            due.actions.push(a);
478	        }
479	        self.next_due = self.next_event();
480	        due
481	    }
482	
483	    pub fn apply(&mut self, a: &Action) {
484	        self.next_due = 0;
485	        match *a {
486	            Action::Key { id, down } => {
487	                if self.board == crate::Board::Smk37 {
488	                    self.smk.key(id, down, self.cycles, self.smk_vel);
489	                } else if (id as usize) < 41 {
490	                    self.keys_down[id as usize] = down;
491	                }
492	            }
493	            Action::Enc { enc, clicks } => {
494	                let n = if self.board == crate::Board::Smk37 { crate::smk::NENC } else { 7 };
495	                if (enc as usize) < n {
496	                    // one detent = one full quadrature cycle (4 transitions);
497	                    // clockwise runs the Gray sequence backwards (Felucca
498	                    // flips the stock decoder's sign: + = clockwise)
499	                    self.enc_pending[enc as usize] -= clicks * 4;
500	                    self.enc_next[enc as usize] = self.cycles;
501	                }
502	            }
503	            Action::Adc { ch, value } if self.board == crate::Board::Smk37 => self.smk.set_analog(ch, value),
504	            Action::Vel { us } => self.smk_vel = (self.hz as u128 * us as u128 / 1_000_000) as u64,
505	            Action::Adc { ch, value } => {
506	                if (ch as usize) < 16 {
507	                    self.adc_value[ch as usize] = value.min(1023);
508	                }
509	            }
510	            Action::Midi { b } => {
511	                // a USB keyboard can send faster than the 31250-baud jack takes it: past a
512	                // second's worth of backlog the bytes are dropped rather than played late
513	                if self.uart.q.len() >= MIDI_QUEUE_MAX {
514	                    self.uart.dropped += 1;
515	                    return;
516	                }
517	                if self.uart.q.is_empty() {
518	                    self.uart.next = self.uart.next.min(self.cycles + self.midi_byte_time());
519	                }
520	                self.uart.q.push_back(b);
521	            }
522	        }
523	    }
524	
525	    // ---- UART1 (MIDI IN) ------------------------------------------------------
526	
527	    fn midi_byte_time(&self) -> u64 {
528	        (self.hz * MIDI_BYTE_BITS / MIDI_BAUD).max(1)
529	    }
530	
531	    /// The next queued byte has arrived: where the RX DMA writes it (None: dropped).
532	    fn uart_receive(&mut self) -> Option<(u32, u8)> {
533	        let b = self.uart.q.pop_front()?;
534	        self.uart.next = if self.uart.q.is_empty() { u64::MAX } else { self.cycles + self.midi_byte_time() };
535	        let u = &mut self.uart;
536	        let len = u.rxeadr.wrapping_sub(u.rxsadr);
537	        if u.con0 & 0x41 != 0x41 || len == 0 || len > 0x10000 {
538	            u.dropped += 1;
539	            return None;
540	        }
541	        let at = u.rxsadr + u.wr % len;
542	        u.wr = (u.wr + 1) % len;
543	        u.since += 1;
544	        if u.rxcnt != 0 && u.since >= u.rxcnt {
545	            u.rpnd = true;
546	        }
547	        // the timeout: OTCNT UART clocks after the last byte (at least a byte time)
548	        let ot = (u.otcnt as u64 * self.hz / UART_HZ).max(self.midi_byte_time());
549	        self.uart.ot_next = self.cycles + ot;
550	        self.uart_update();
551	        Some((at, b))
552	    }
553	
554	    fn uart_update(&mut self) {
555	        let u = &self.uart;
556	        self.uart_irq = (u.con0 & 0x08 != 0 && u.rpnd) || (u.con0 & 0x20 != 0 && u.otpnd) || (u.con0 & 0x04 != 0 && u.tpnd);
557	    }
558	
559	    /// MIDI bytes waiting to arrive (the queue behind the jack).
560	    pub fn midi_queued(&self) -> usize {
561	        self.uart.q.len()
562	    }
563	
564	    /// MIDI bytes dropped (no receiver set up: the UART off or no DMA ring; or a full queue).
565	    pub fn midi_dropped(&self) -> u64 {
566	        self.uart.dropped
567	    }
568	
569	    /// One cycle; true when something timed is due (call `advance(0)`).
570	    #[inline(always)]
571	    pub fn tick(&mut self) -> bool {
572	        self.cycles += 1;
573	        self.cycles >= self.next_due
574	    }
