576	    /// Ticks that can pass before one is due (a tick is due once cycles reach next_due).
577	    #[inline]
578	    pub fn tick_room(&self) -> u64 {
579	        self.next_due.saturating_sub(self.cycles + 1).min(self.room_cap)
580	    }
581	
582	    #[inline]
583	    pub fn next_tick_due(&self) -> bool {
584	        self.cycles + 1 >= self.next_due
585	    }
