587	    /// Any interrupt source pending at all (before enables and priorities).
588	    #[inline(always)]
589	    pub fn any_pending(&self) -> bool {
590	        self.t5_pending || self.alnk_pend & 0xf0 != 0 || self.ilat != 0 || self.tick_pending || self.spi1_pending
591	            || self.tmr.iter().any(|t| t.pending) || self.adc_irq || self.spi2_pending || self.uart_irq
592	    }
593	
594	    /// The highest-priority source cpu0 has enabled and that is pending: (irq, prio).
595	    pub fn pending_irq(&self) -> Option<(u8, u8)> {
596	        self.pending_irq_for(0)
597	    }
598	
599	    /// The same for core `core` (its own enable bank).
600	    pub fn pending_irq_for(&self, core: u32) -> Option<(u8, u8)> {
601	        let bank = if core == 0 { &self.icfg } else { &self.icfg1 };
602	        let icfg = |n: u8| bank[(n >> 3) as usize];
603	        if !self.any_pending() {
604	            return None;
605	        }
606	        let mut best: Option<(u8, u8)> = None;
607	        let mut consider = |n: u8| {
608	            let nib = (icfg(n) >> ((n & 7) * 4)) & 0xf;
609	            if nib & 1 != 0 {
610	                let prio = ((nib >> 1) & 7) as u8;
611	                if best.map_or(true, |(_, p)| prio > p) {
612	                    best = Some((n, prio));
613	                }
614	            }
615	        };
616	        if self.t5_pending {
617	            consider(IRQ_TIMER5);
618	        }
619	        if self.tick_pending {
620	            consider(IRQ_OS_TICK);
621	        }
622	        if self.spi1_pending {
623	            consider(IRQ_SPI1);
624	        }
625	        if self.adc_irq {
626	            consider(IRQ_SARADC);
627	        }
628	        if self.spi2_pending {
629	            consider(IRQ_SPI2);
630	        }
631	        if self.uart_irq {
632	            consider(IRQ_UART1);
633	        }
634	        for i in 0..4 {
635	            if self.tmr[i].pending {
636	                consider(4 + i as u8);
637	            }
638	        }
639	        if self.alnk_pend & 0xf0 != 0 && self.alnk_con0 & 0x800 != 0 {
640	            consider(IRQ_ALNK0);
641	        }
642	        for b in 0..8u8 {
643	            if self.ilat & (1 << b) != 0 {
644	                consider(120 + b);
645	            }
646	        }
647	        best
648	    }
