651	
652	    /// Reads handled here; `None` = plain SFR storage.
653	    pub fn read(&mut self, addr: u32) -> Option<u32> {
654	        Some(match addr {
655	            0x10800 => self.t4_con,
656	            0x10804 => {
657	                if self.t4_con & 1 == 0 {
658	                    return Some(0);
659	                }
660	                // three reads close together outside ISRs: a polling loop.
661	                // (Reads inside an ISR neither count nor trigger: a single
662	                // main-loop read right after the tick ISR's own read once
663	                // skipped time in ui_input and the notes went silent.)
664	                if self.skip_idle && !self.in_isr {
665	                    if self.cycles - self.last_cnt_read < 64 {
666	                        self.cnt_streak += 1;
667	                    } else {
668	                        self.cnt_streak = 0;
669	                    }
670	                    if self.cnt_streak >= 2 {
671	                        // never past the next event, and at most 20 us at a
672	                        // time: the loop re-checks its own deadline (an
673	                        // uncapped jump once crossed a whole boot delay)
674	                        let next = self.next_event().min(self.cycles + self.hz / 50_000);
675	                        if next > self.cycles + 1 {
676	                            self.skipped += next - 1 - self.cycles;
677	                            self.cycles = next - 1;
678	                            self.next_due = 0;
679	                        }
680	                    }
681	                    self.last_cnt_read = self.cycles;
682	                }
683	                ((self.cycles - self.t4_base) as u128 * T4_HZ as u128 / self.hz as u128) as u32
684	            }
685	            0x10400 | 0x10500 | 0x10600 | 0x10700 => {
686	                let t = &self.tmr[((addr - 0x10400) >> 8) as usize];
687	                t.con | if t.pending { 0x8000 } else { 0 }
688	            }
689	            0x10404 | 0x10504 | 0x10604 | 0x10704 => {
690	                let i = ((addr - 0x10400) >> 8) as usize;
691	                let t = self.tmr[i];
692	                if t.next == u64::MAX {
693	                    t.cnt0
694	                } else {
695	                    t.cnt0 + ((self.cycles - t.start) / self.tmr_cycles_per_count(i).max(1)) as u32
696	                }
697	            }
698	            0x10408 | 0x10508 | 0x10608 | 0x10708 => self.tmr[((addr - 0x10400) >> 8) as usize].prd,
699	            0x10900 => self.t5_con | if self.t5_pending { 0x8000 } else { 0 },
700	            0x10904 => {
701	                if self.t5_con & 1 != 0 && self.t5_next != u64::MAX {
702	                    let period = self.t5_period();
703	                    let into = period - (self.t5_next - self.cycles).min(period);
704	                    ((into * T5_HZ / self.hz) % self.t5_prd.max(1) as u64) as u32
705	                } else {
706	                    0
707	                }
708	            }
709	            0x10908 => self.t5_prd,
710	            0x12e00 => (self.alnk_con0 & !0x8000) | (self.alnk_half << 15),
711	            0x12e04 => self.alnk_con1,
712	            0x12e08 => self.alnk_pend,
713	            0x12e0c => self.alnk_con3,
714	            0x12e1c => self.alnk_adr,
715	            0x12e20 => self.alnk_len,
716	            // conversions are instant: done (bit 7) once started. Bit 4 reads as written
717	            // (Felucca's `|= 0x40` read-modify-write must keep it); the stock scan's "skip
718	            // while bit 4" passes because its IRQ 24 handler writes CON = 0x40, then 0.
719	            0x13100 => (self.adc_con & !0x80) | if self.adc_done { 0x80 } else { 0 },
720	            0x13104 if self.board == crate::Board::Smk37 => self.adc_sample as u32,
721	            0x13104 => self.adc_value[((self.adc_con >> 8) & 0xf) as usize] as u32,
722	            // the latch's set word reads the pending bits; its clear word reads 0: the stock
723	            // IRQ 122 handler acknowledges with `[0x1EEF1A4] |= 4`, and a read-back of every
724	            // pending bit there cleared a pending context switch too (a task ran on after
725	            // blocking and was queued on its wait list twice)
726	            0x1eef1a0 => self.ilat,
727	            0x1eef1a4 => 0,
728	            0x1eef100..=0x1eef17f => self.icfg[((addr - 0x1eef100) / 4) as usize],
729	            0x1eef300..=0x1eef37f => self.icfg1[((addr - 0x1eef300) / 4) as usize],
730	            0x1eef0ec => self.tick_ctl | if self.tick_pending { 0x80 } else { 0 },
731	            0x1eef0f0 => {
732	                // how far into the period, in the period register's units
733	                if self.tick_next == u64::MAX {
734	                    0
735	                } else {
736	                    let into = (self.cycles - self.tick_start).min(self.tick_period());
737	                    (into as u128 * self.tick_prd as u128 / self.tick_period() as u128) as u32
738	                }
739	            }
740	            0x1eef0f4 => self.tick_prd,
741	            0x12100 => {
742	                let u = &self.uart;
743	                u.con0 | (u.otpnd as u32) << 11 | (u.rpnd as u32) << 14 | (u.tpnd as u32) << 15
744	            }
745	            0x1211c => self.uart.rxsadr,
746	            0x12120 => self.uart.rxeadr,
747	            0x12124 => self.uart.rxcnt,
748	            0x12110 => self.uart.otcnt,
749	            0x12128 => self.uart.hrxcnt,
750	            0x50004 if self.board == crate::Board::Smk37 => self.smk_pa_in(),
751	            0x501c4 if self.board == crate::Board::Smk37 => self.smk_ph_in(),
752	            0x50004 => self.pa_in(),
753	            0x50044 => self.pb_in(),
754	            _ => return None,
755	        })
756	    }
757	
758	    /// Writes handled here; returns false for plain SFR storage.
759	    pub fn write(&mut self, addr: u32, v: u32) -> bool {
760	        // a timer or DMA may have been (re)programmed: the runner services the SoC before the
761	        // next instruction (leaving compiled code). Not for the FM-1's ADC: its conversions are
762	        // instant, so a write there changes only whether IRQ 24 is raised (then it does).
763	        // OberVave converts ~1 M times a second, 5 writes each: every one left the JIT.
764	        if !(matches!(addr, 0x13100 | 0x13104) && self.board != crate::Board::Smk37) {
765	            self.next_due = 0;
766	        }
767	        match addr {
768	            0x10800 => {
769	                if self.t4_con & 1 == 0 && v & 1 != 0 {
770	                    self.t4_base = self.cycles;
771	                }
772	                self.t4_con = v & !0x4000;
773	            }
774	            0x10804 => self.t4_base = self.cycles,
775	            0x10808 => {}
776	            0x10900 => {
777	                if v & 0x4000 != 0 {
778	                    self.t5_pending = false;
779	                }
780	                let was = self.t5_con & 1;
781	                self.t5_con = v & !0xc000;
782	                if was == 0 && v & 1 != 0 {
783	                    self.t5_next = self.cycles + self.t5_period();
784	                } else if v & 1 == 0 {
785	                    self.t5_next = u64::MAX;
786	                }
787	            }
788	            0x10904 => {}
789	            0x10908 => self.t5_prd = v,
790	            0x10400 | 0x10500 | 0x10600 | 0x10700 => {
791	                let i = ((addr - 0x10400) >> 8) as usize;
792	                if v & 0x4000 != 0 {
793	                    self.tmr[i].pending = false;
794	                }
795	                self.tmr[i].con = v & !0xc000;
796	                self.tmr_arm(i);
797	            }
798	            0x10404 | 0x10504 | 0x10604 | 0x10704 => {
799	                let i = ((addr - 0x10400) >> 8) as usize;
800	                self.tmr[i].cnt0 = v;
801	                self.tmr_arm(i);
802	            }
803	            0x10408 | 0x10508 | 0x10608 | 0x10708 => {
804	                let i = ((addr - 0x10400) >> 8) as usize;
805	                self.tmr[i].prd = v;
806	                self.tmr_arm(i);
807	            }
808	            0x12e00 => {
809	                let was = self.alnk_con0 & 0x800;
810	                self.alnk_con0 = v & 0xffff & !0x8000;
811	                if was == 0 && v & 0x800 != 0 {
812	                    self.alnk_half = 0;
813	                    self.alnk_next = self.cycles + self.half_period();
814	                } else if v & 0x800 == 0 {
815	                    self.alnk_next = u64::MAX;
816	                }
817	            }
818	            0x12e04 => self.alnk_con1 = v & 0xffff,
819	            0x12e08 => self.alnk_pend &= !((v & 0xf) << 4), // bits 0-3 clear pendings 4-7
820	            0x12e0c => self.alnk_con3 = v & 0xff,
821	            0x12e1c => self.alnk_adr = v,
822	            0x12e20 => self.alnk_len = v & 0xffff,
823	            0x13100 => {
824	                // bit 6 with bit 4 (enable) starts a conversion, which finishes at once; with
825	                // bit 5 it raises IRQ 24 (the stock driver reads RES in that handler). Bit 6
826	                // without bit 4 acknowledges (`CON = 0x40`).
827	                if v & 0x40 != 0 {
828	                    if v & 0x10 != 0 {
829	                        if self.board == crate::Board::Smk37 {
830	                            // SMK-37: sampled now, from the mux address latched now; done ~40 us
831	                            // later (the hardware map's SMK timing), IRQ 24 then if enabled
832	                            let ch = (v >> 8) & 0xf;
833	                            self.adc_sample = self.smk.adc(ch).unwrap_or(self.adc_value[ch as usize]);
834	                            self.adc_done = false;
835	                            self.adc_irq = false;
836	                            self.adc_next = self.cycles + (self.hz / 25_000).max(1);
837	                            self.next_due = 0;
838	                        } else {
839	                            self.adc_done = true;
840	                            if self.adc_irq != (v & 0x20 != 0) {
841	                                self.next_due = 0;
842	                            }
843	                            self.adc_irq = v & 0x20 != 0;
844	                        }
845	                    } else {
846	                        if self.adc_irq {
847	                            self.next_due = 0;
848	                        }
849	                        self.adc_done = false;
850	                        self.adc_irq = false;
851	                    }
852	                }
853	                self.adc_con = v;
854	            }
855	            0x13104 => {}
856	            0x1eef100..=0x1eef17f => self.icfg[((addr - 0x1eef100) / 4) as usize] = v,
857	            0x1eef300..=0x1eef37f => self.icfg1[((addr - 0x1eef300) / 4) as usize] = v,
858	            0x1eef0ec => {
859	                if v & 0x40 != 0 {
860	                    self.tick_pending = false;
861	                }
862	                let was = self.tick_ctl & 1;
863	                self.tick_ctl = v & 0x3f;
864	                if was == 0 && v & 1 != 0 {
865	                    self.tick_start = self.cycles;
866	                    self.tick_next = self.cycles + self.tick_period();
867	                } else if v & 1 == 0 {
868	                    self.tick_next = u64::MAX;
869	                }
870	            }
871	            0x1eef0f0 => {
872	                self.tick_start = self.cycles;
873	                if self.tick_next != u64::MAX {
874	                    self.tick_next = self.cycles + self.tick_period();
875	                }
876	            }
877	            0x1eef0f4 => self.tick_prd = v,
878	            0x1eef1a0 => self.ilat |= v,
879	            0x1eef1a4 => self.ilat &= !v,
880	            0x12100 => {
881	                let u = &mut self.uart;
882	                if v & 0x80 != 0 {
883	                    u.hrxcnt = u.since;
884	                    u.since = 0;
885	                }
886	                if v & 0x400 != 0 {
887	                    u.otpnd = false;
888	                }
889	                if v & 0x1000 != 0 {
890	                    u.rpnd = false;
891	                }
892	                if v & 0x2000 != 0 {
893	                    u.tpnd = false;
894	                }
895	                u.con0 = v & 0xffff & !0xfc80;
896	                self.uart_update();
897	            }
898	            // the ring's start resets the DMA's write position
899	            0x1211c => {
900	                self.uart.rxsadr = v;
901	                self.uart.wr = 0;
902	            }
903	            0x12120 => self.uart.rxeadr = v,
904	            0x12124 => self.uart.rxcnt = v & 0xffff,
905	            0x12110 => self.uart.otcnt = v,
906	            // TX DMA count: sent at once (MIDI thru has no pin here)
907	            0x12118 => {
908	                self.uart.tpnd = true;
909	                self.uart_update();
910	                return false;
911	            }
912	            0x50000 if self.board == crate::Board::Smk37 => {
913	                // PA1's rising edge latches the 595 chain (SPI2 shifts it)
914	                if self.pa_out & 2 == 0 && v & 2 != 0 {
915	                    self.smk.latch();
916	                }
917	                self.pa_out = v;
918	            }
919	            0x501c0 if self.board == crate::Board::Smk37 => self.ph_out = v,
920	            0x50000 => {
921	                self.led_credit();
922	                self.pa_write(v);
923	            }
924	            0x501c0 => {
925	                self.led_credit();
926	                self.ph_out = v;
927	            }
928	            _ => return false,
929	        }
930	        true
931	    }
