933	    // ---- LEDs ---------------------------------------------------------------
934	    // LED lines PA9, PA10, PH6, PH9 light the LED in the latched column on
935	    // row bit 1, 2, 3, 4 (hal/fm1_input.h fm1__led_lines); the LED belongs to
936	    // the key or button at that (row, column) of the matrix.
937	
938	    fn led_credit(&mut self) {
939	        let dt = self.cycles - self.led_last;
940	        self.led_last = self.cycles;
941	        if dt == 0 {
942	            return;
943	        }
944	        let lines = ((self.pa_out >> 8) & 2) | ((self.pa_out >> 8) & 4) | ((self.ph_out >> 3) & 8) | ((self.ph_out >> 5) & 16);
945	        if lines == 0 {
946	            return;
947	        }
948	        for col in 0..11usize {
949	            if self.sr_latched & (1 << col) != 0 {
950	                continue;
951	            }
952	            for row in 1..5usize {
953	                if lines & (1 << row) != 0 {
954	                    let id = KEYMAP[row][col];
955	                    if id >= 0 {
956	                        self.led_acc[id as usize] += dt;
957	                    }
958	                }
959	            }
960	        }
961	    }
962	
963	    /// The fraction of time each LED was lit since the last call.
964	    pub fn led_take(&mut self) -> [f32; 41] {
965	        self.led_credit();
966	        let span = (self.cycles - self.led_since).max(1) as f32;
967	        self.led_since = self.cycles;
968	        let mut out = [0f32; 41];
969	        for (o, a) in out.iter_mut().zip(self.led_acc.iter_mut()) {
970	            *o = *a as f32 / span;
971	            *a = 0;
972	        }
973	        out
974	    }
