976	    // ---- key matrix -----------------------------------------------------
977	
978	    /// cpu0 executed `idle` (it sleeps until an interrupt): with `skip_idle` and nothing
979	    /// pending, time jumps to just before the next event, where the interrupt that wakes it
980	    /// comes from. The stock firmware's idle task runs it on every pass.
981	    pub fn idle(&mut self) {
982	        if !self.skip_idle || self.any_pending() {
983	            return;
984	        }
985	        let next = self.next_event();
986	        if next != u64::MAX && next > self.cycles + 1 {
987	            self.skipped += next - 1 - self.cycles;
988	            self.cycles = next - 1;
989	            self.next_due = 0;
990	        }
991	    }
992	
993	    /// SMK-37: an SPI1 transfer of `bytes` started at BAUD `baud` (the clock 60 MHz / (baud + 1):
994	    /// ~12 MHz at 4 for the LCD, 6.67 MHz at 8 for the pad LEDs); with `irq` IRQ 16 at its end.
995	    pub fn spi1_start(&mut self, bytes: u32, baud: u32, irq: bool) {
996	        let clk = 60_000_000 / (baud as u64 + 1);
997	        let dur = (bytes.max(1) as u64 * 8 * self.hz / clk).max(1);
998	        self.spi1_done_at = self.cycles + dur;
999	        if irq {
1000	            self.spi1_irq_at = self.spi1_done_at;
1001	            self.next_due = 0;
1002	        }
1003	    }
1004	
1005	    /// A SPI2 transfer of `bytes` started (with its interrupt enabled when `irq`): it takes
1006	    /// 16 * (baud + 1) peripheral clocks a byte (48 MHz assumed), so the stock firmware's
1007	    /// interrupt-driven column scan runs at a hardware-like pace instead of back to back.
1008	    pub fn spi2_start(&mut self, bytes: u32, baud: u32, irq: bool) {
1009	        self.next_due = 0;
1010	        if irq {
1011	            let clocks = bytes.max(1) as u64 * 16 * (baud as u64 + 1);
1012	            self.spi2_next = self.cycles + (clocks * self.hz / 48_000_000).max(1);
1013	        }
1014	    }
1015	
1016	    /// A byte clocked into the 74HC595 chain by SPI2, MSB first (the stock firmware drives
1017	    /// the matrix columns this way; Felucca bit-bangs SER/SRCLK on PA4/PA3). RCLK (PA1)
1018	    /// still latches.
1019	    pub fn sr_shift_byte(&mut self, b: u8) {
1020	        if self.board == crate::Board::Smk37 {
1021	            return self.smk.spi2_byte(b);
1022	        }
1023	        for bit in (0..8).rev() {
1024	            self.sr_shift = (self.sr_shift << 1) | ((b >> bit) & 1) as u16;
1025	        }
1026	    }
1027	
1028	    fn pa_write(&mut self, v: u32) {
1029	        let old = self.pa_out;
1030	        self.pa_out = v;
1031	        if old & 8 == 0 && v & 8 != 0 {
1032	            // SRCLK rising edge: shift SER (PA4) in, MSB first
1033	            self.sr_shift = (self.sr_shift << 1) | ((v >> 4) & 1) as u16;
1034	        }
1035	        if old & 2 == 0 && v & 2 != 0 {
1036	            // RCLK rising edge: outputs follow the shift register
1037	            self.sr_latched = self.sr_shift;
1038	        }
1039	    }
1040	
1041	    /// Row bits (0..5) pulled low by a closed contact in a selected column.
1042	    fn closed_rows(&self) -> u32 {
1043	        let mut rows = 0u32;
1044	        for col in 0..11usize {
1045	            if self.sr_latched & (1 << col) != 0 {
1046	                continue; // column not selected (active low)
1047	            }
1048	            for row in 0..6usize {
1049	                let id = KEYMAP[row][col];
1050	                if id >= 0 && self.keys_down[id as usize] {
1051	                    rows |= 1 << row;
1052	                }
1053	            }
1054	            for (i, e) in ENC.iter().enumerate() {
1055	                let (a, b) = GRAY[self.enc_state[i] as usize];
1056	                if e[0] as usize == col && a != 0 {
1057	                    rows |= 1 << e[1];
1058	                }
1059	                if e[2] as usize == col && b != 0 {
1060	                    rows |= 1 << e[3];
1061	                }
1062	            }
1063	        }
1064	        rows
1065	    }
1066	
1067	    fn pa_in(&self) -> u32 {
1068	        let r = self.closed_rows();
1069	        // row 0 = PA0, rows 1-4 = PA5..PA8; everything else reads as pulled up
1070	        let low = (r & 1) | ((r & 0x1e) << 4);
1071	        (self.pa_out | 0xffff) & !low
1072	    }
1073	
1074	    /// SMK-37: the matrix rows closed in the latched column(s).
1075	    fn smk_rows(&self) -> u32 {
1076	        self.smk.rows(self.cycles, |i| {
1077	            let (a, b) = GRAY[self.enc_state[i] as usize];
1078	            (a != 0, b != 0)
1079	        })
1080	    }
1081	
1082	    /// SMK-37 rows 0..4 on PA2, PA5..PA7, PA9 (pulled up: low = closed).
1083	    fn smk_pa_in(&self) -> u32 {
1084	        let r = self.smk_rows();
1085	        let low = (r & 1) << 2 | (r & 0xe) << 4 | (r & 0x10) << 5;
1086	        (self.pa_out | 0xffff) & !low
1087	    }
1088	
1089	    /// SMK-37 rows 5..7 on PH6, PH8, PH9.
1090	    fn smk_ph_in(&self) -> u32 {
1091	        let r = self.smk_rows();
1092	        let low = (r & 0x20) << 1 | (r & 0xc0) << 2;
1093	        (self.ph_out | 0xffff) & !low
1094	    }
1095	
1096	    fn pb_in(&self) -> u32 {
1097	        let r = self.closed_rows();
1098	        0xffff & !(((r >> 5) & 1) << 7)
1099	    }
1100	}
1101	
1102	/// Logical names from Felucca's panel.c mapped to matrix key ids.
1103	pub fn key_id(name: &str) -> Option<u8> {
1104	    let n = name.to_ascii_uppercase();
1105	    let buttons = [
1106	        ("OCTDN", 0), ("OCTUP", 1), ("FX", 2), ("SCL", 3), ("ENV", 4), ("LFO", 5), ("EDIT", 6),
1107	        ("GLO", 7), ("HOME", 8), ("SAVE", 9), ("ARP", 10), ("SEQ", 11), ("PLAY", 12), ("REC", 13),
1108	    ];
1109	    if let Some((_, id)) = buttons.iter().find(|(b, _)| *b == n) {
1110	        return Some(*id);
1111	    }
1112	    if let Some(k) = n.strip_prefix('K') {
1113	        return k.parse::<u8>().ok().filter(|&k| k < 41);
1114	    }
1115	    if let Some(k) = note_name(&n) {
1116	        return Some(14 + k);
1117	    }
1118	    if let Some(note) = n.strip_prefix('N') {
1119	        // note keys: n0 = F3 .. n26 = G5
1120	        return note.parse::<u8>().ok().filter(|&k| k < 27).map(|k| 14 + k);
1121	    }
1122	    None
1123	}
1124	
1125	/// Encoder names (panel.c PANEL_DEFAULT) to matrix encoder index.
1126	pub fn enc_id(name: &str) -> Option<u8> {
1127	    let n = name.to_ascii_uppercase();
1128	    match n.as_str() {
1129	        "SELECT" => Some(0),
1130	        "ALGO" | "ALGORITHM" => Some(1),
1131	        "PRESET" | "PRESETS" => Some(6),
1132	        "K1" => Some(2),
1133	        "K2" => Some(3),
1134	        "K3" => Some(4),
1135	        "K4" => Some(5),
1136	        _ => n.strip_prefix("ENC").and_then(|e| e.parse::<u8>().ok()).filter(|&e| e < 7),
1137	    }
1138	}
1139	
1140	/// `C4`, `F#3`, `Bb4` -> note-key index (0 = F3 .. 26 = G5).
1141	fn note_name(n: &str) -> Option<u8> {
1142	    let b = n.as_bytes();
1143	    let base = match *b.first()? {
1144	        b'C' => 0, b'D' => 2, b'E' => 4, b'F' => 5, b'G' => 7, b'A' => 9, b'B' => 11,
1145	        _ => return None,
1146	    };
1147	    let (acc, rest) = match b.get(1) {
1148	        Some(b'#') => (1, &n[2..]),
1149	        Some(b'B') if b.len() == 3 => (-1, &n[2..]), // "BB4" after uppercasing = Bb4
1150	        _ => (0, &n[1..]),
1151	    };
1152	    let oct: i32 = rest.parse().ok()?;
1153	    let midi = (oct + 1) * 12 + base + acc;
1154	    let k = midi - 53; // F3 = MIDI 53
1155	    (0..27).contains(&k).then_some(k as u8)
1156	}
1157	
1158	#[cfg(test)]
1159	mod tests {
1160	    use super::*;
1161	
1162	    /// Advance to `cycle`, collecting the bytes the UART's DMA wrote.
1163	    fn run_to(p: &mut Periph, cycle: u64, got: &mut Vec<(u32, u8)>) {
1164	        while p.cycles < cycle {
1165	            let step = p.next_event().min(cycle).max(p.cycles + 1) - p.cycles;
1166	            if let Some(w) = p.advance(step).uart_rx {
1167	                got.push(w);
1168	            }
1169	        }
1170	    }
1171	
1172	    #[test]
1173	    fn uart_midi_in_dma_latch_and_timeout() {
1174	        let mut p = Periph::default();
1175	        // Felucca's set-up (hal/fm1_uart.h) with a 4-byte ring, plus the RX and timeout IRQs
1176	        p.write(0x1211c, 0x1000);
1177	        p.write(0x12120, 0x1004);
1178	        p.write(0x12124, 4);
1179	        p.write(0x12110, 48_000); // 1 ms of silence
1180	        p.write(0x12100, 0x40 | 0x08 | 0x20 | 1);
1181	        for b in [0x90, 0x3c, 0x64, 0x80, 0x3c] {
1182	            p.apply(&Action::Midi { b });
1183	        }
1184	        let byte = p.midi_byte_time();
1185	        let mut got = Vec::new();
1186	        run_to(&mut p, 3 * byte, &mut got);
1187	        assert_eq!(got, [(0x1000, 0x90), (0x1001, 0x3c), (0x1002, 0x64)]); // a byte time apart
1188	        assert!(p.pending_irq_for(0).is_none() && !p.any_pending()); // IRQ 20 not enabled yet
1189	        p.icfg[(IRQ_UART1 >> 3) as usize] |= 1 << ((IRQ_UART1 & 7) * 4);
1190	        run_to(&mut p, 5 * byte, &mut got);
1191	        assert_eq!(got[3..], [(0x1003, 0x80), (0x1000, 0x3c)]); // the ring wraps
1192	        assert_eq!(p.read(0x12100).unwrap() & 0x4000, 0x4000); // RXCNT (4) bytes: RX pending
1193	        assert_eq!(p.pending_irq_for(0).map(|(n, _)| n), Some(IRQ_UART1));
1194	        // the handler's acknowledge: latch the count, clear the pending
1195	        let con = p.read(0x12100).unwrap();
1196	        p.write(0x12100, con | 0x80);
1197	        let con = p.read(0x12100).unwrap();
1198	        p.write(0x12100, con | 0x1000);
1199	        assert_eq!(p.read(0x12128), Some(5));
1200	        assert!(p.pending_irq_for(0).is_none());
1201	        // a millisecond of silence after the last byte: the timeout
1202	        let ms = p.hz / 1000;
1203	        run_to(&mut p, 5 * byte + ms + 1, &mut got);
1204	        assert_eq!(p.read(0x12100).unwrap() & 0x800, 0x800);
1205	        assert_eq!(p.pending_irq_for(0).map(|(n, _)| n), Some(IRQ_UART1));
1206	        let con = p.read(0x12100).unwrap();
1207	        p.write(0x12100, con | 0x80 | 0x400);
1208	        assert_eq!(p.read(0x12128), Some(0));
1209	        assert!(p.pending_irq_for(0).is_none());
1210	        // with the UART off a byte is dropped
1211	        p.write(0x12100, 0);
1212	        p.apply(&Action::Midi { b: 0xf8 });
1213	        run_to(&mut p, 7 * byte + ms, &mut got);
1214	        assert_eq!((got.len(), p.midi_dropped()), (5, 1));
1215	    }
1216	}
