                    .min(W as u16 - 1);
            }
            0x2B => {
                self.window.1 = u16::from_be_bytes([self.arg[0], self.arg[1]]);
                self.window.3 = u16::from_be_bytes([self.arg[2], self.arg[3]])
                    .min(H as u16 - 1);
            }
            _ => {}
        }
