/* SPDX-License-Identifier: MIT */
/* SPDX-FileCopyrightText: 2026 japes98 */
/* Audio out: a buffer of two halves of LEN words (L/R int32, the 16-bit
   sample << 8), refilled with a rising ramp on each half-done interrupt
   (IRQ 11); the main loop sleeps with `idle`. Blocks done in OUT(0). */
#include "board.h"
#define LEN 64u
#define BUF ((volatile s32 *)0x01c10000u)
/* the ramp's next value (no .bss in test images) */
#define next (*(volatile s32 *)0x01c000f0u)
static void refill(u32 half)
{
    volatile s32 *p = BUF + half * LEN;
    for (u32 i = 0; i < LEN; i += 2) {
        p[i] = next << 8;
        p[i + 1] = -next << 8;
        next = (next + 97) & 0x7fff;
    }
}
__attribute__((interrupt)) void alnk_isr(void)
{
    ALNK_PEND = 8u;
    refill(((ALNK_CON0 >> 15) & 1u) ^ 1u);
    OUT(0)++;
}
int main(void)
{
    refill(0);
    refill(1);
    VECTOR(IRQ_ALNK) = (u32)alnk_isr;
    ICFG(IRQ_ALNK) = ICFG_ON(IRQ_ALNK, 1u);
    ALNK_ADR = (u32)BUF;
    ALNK_LEN = LEN;
    ALNK_CON0 = 0x800u;
    irq_on();
    for (;;)
        __asm__ volatile("idle");
}
/* SPDX-License-Identifier: MIT */
/* SPDX-FileCopyrightText: 2026 japes98 */
/* A marker word, then a counter that never stops: `completed`, and the
   watchdog never fires. */
#include "board.h"
int main(void)
{
    OUT(0) = 0x600df00du;
    for (;;)
        OUT(1)++;
}
/* SPDX-License-Identifier: MIT */
/* SPDX-FileCopyrightText: 2026 japes98 */
/* Scans the key matrix's 11 columns (one selected at a time through the
   74HC595 chain) and keeps each column's closed rows in OUT(c) (row 0 = PA0,
   rows 1-4 = PA5..PA8, row 5 = PB7; low = closed, periph.rs closed_rows).
   Also counts the changes of encoder 0's two contacts (column 0 row 0 and
   column 1 row 0) in OUT(16): four per detent. */
#include "board.h"
static void columns(u32 bits)
{
    for (int i = 15; i >= 0; i--) {
        u32 ser = ((bits >> i) & 1u) << 4;
        PA_OUT = ser;
        PA_OUT = ser | 8u;
    }
    PA_OUT = 2u;
    PA_OUT = 0u;
}
static u32 rows(void)
{
    u32 a = ~PA_IN, b = ~PB_IN;
    return (a & 1u) | ((a >> 4) & 0x1eu) | (((b >> 7) & 1u) << 5);
}
int main(void)
{
    u32 last = 0;
    for (;;) {
        for (u32 c = 0; c < 11; c++) {
            columns(0xffffu & ~(1u << c));
            OUT(c) = rows();
        }
        u32 enc = (OUT(0) & 1u) | ((OUT(1) & 1u) << 1);
        if (enc != last) {
            OUT(16)++;
            last = enc;
        }
    }
}
/* SPDX-License-Identifier: MIT */
/* SPDX-FileCopyrightText: 2026 japes98 */
/* Four coloured quadrants and a diagonal, one byte at a time through SPI1
   (column/row address set, memory write), then halt. */
#include "board.h"
static void cmd(u32 c) { PC_OUT = 0; SPI1_BUF = c; }
static void dat(u32 d) { PC_OUT = 0x100; SPI1_BUF = d; }
static void window(u32 x0, u32 y0, u32 x1, u32 y1)
{
    cmd(0x2a); dat(x0 >> 8); dat(x0); dat(x1 >> 8); dat(x1);
    cmd(0x2b); dat(y0 >> 8); dat(y0); dat(y1 >> 8); dat(y1);
    cmd(0x2c);
}
static void fill(u32 x0, u32 y0, u32 x1, u32 y1, u32 rgb565)
{
    window(x0, y0, x1, y1);
    for (u32 n = (x1 - x0 + 1) * (y1 - y0 + 1); n; n--) {
        dat(rgb565 >> 8);
        dat(rgb565);
    }
}
int main(void)
{
    cmd(0x11);
    cmd(0x29);
    fill(0, 0, 119, 119, 0xf800);
    fill(120, 0, 239, 119, 0x07e0);
    fill(0, 120, 119, 239, 0x001f);
    fill(120, 120, 239, 239, 0xffff);
    for (u32 i = 0; i < 240; i++)
        fill(i, i, i, i, 0x0000);
    return 0;
}

