        for (u32 c = 0; c < 11; c++) {
            select_column(c);
            u32 r = rows();
            if (r != STATE[c]) {
                STATE[c] = r;
                if (OUT(15) < 256u)
                    LOG[OUT(15)++] = (c << 8) | r;
            }
        }
    }
}
