    VECTOR(IRQ_ALNK) = (u32)alnk_isr;
    ICFG(IRQ_ALNK) = ICFG_ON(IRQ_ALNK, 1u);
    ALNK_ADR3 = (u32)BUF;
    ALNK_LEN = LEN;
    ALNK_CON0 = 0x800u;
    irq_on();
    for (;;)
        __asm__ volatile("idle");
}
